data "aws_ami" "amazon_linux" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }
}

resource "aws_instance" "ec2_instance" {
  ami                         = data.aws_ami.amazon_linux.id
  instance_type               = "t3.micro"
  iam_instance_profile        = aws_iam_instance_profile.ec2_instance_profile.name
  subnet_id                   = aws_subnet.subnet.id
  associate_public_ip_address = true

  vpc_security_group_ids = [
    aws_security_group.sg.id
  ]

  # VULNERABILITY: Sensitive credentials stored in User Data
  user_data = <<-EOF
    #!/bin/bash
    echo "ec2-user:CloudGoatInstancePassword!" | chpasswd
    sed -i 's/PasswordAuthentication no/PasswordAuthentication yes/g' /etc/ssh/sshd_config
    service sshd restart
  EOF

  tags = {
    Name = "cg-sensitive-ec2-${var.cgid}"
    Stack = var.stack-name
    Scenario = var.scenario-name
  }
}

resource "aws_security_group" "sg" {
  name        = "cg-sg-${var.cgid}"
  description = "Allow SSH inbound traffic"
  vpc_id      = aws_vpc.vpc.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = var.cg_whitelist
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "cg-sg-${var.cgid}"
    Stack = var.stack-name
    Scenario = var.scenario-name
  }
}

# 1. Starting User
# Attack Path: Starts here. Can Describe EC2 to find User Data.
resource "aws_iam_user" "start_user" {
  name = "cg-start-user-${var.cgid}"
  tags = {
    Name = "cg-start-user-${var.cgid}"
    Stack = var.stack-name
    Scenario = var.scenario-name
  }
}

resource "aws_iam_access_key" "start_user" {
  user = aws_iam_user.start_user.name
}

resource "aws_iam_user_policy" "start_user_policy" {
  name = "cg-start-user-policy-${var.cgid}"
  user = aws_iam_user.start_user.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ec2:DescribeInstanceAttribute",
          "ec2:DescribeTags"
        ]
        Resource = "*"
      }
    ]
  })
}

# 2. EC2 Instance Role
# Attack Path: Acquired via Metadata (IMDS). Can read Lambda details.
resource "aws_iam_role" "ec2_role" {
  name = "cg-ec2-role-${var.cgid}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Effect = "Allow"
      }
    ]
  })
  tags = {
    Name = "cg-ec2-role-${var.cgid}"
    Stack = var.stack-name
    Scenario = var.scenario-name
  }
}

resource "aws_iam_role_policy" "ec2_role_policy" {
  name = "cg-ec2-policy-${var.cgid}"
  role = aws_iam_role.ec2_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "lambda:ListFunctions",
          "lambda:GetFunction",
          "lambda:GetFunctionConfiguration"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_instance_profile" "ec2_instance_profile" {
  name = "cg-ec2-instance-profile-${var.cgid}"
  role = aws_iam_role.ec2_role.name
}

# 3. Hidden User (Stored in Lambda)
# Attack Path: Credentials found in Lambda Env Vars. Can read Secrets.
resource "aws_iam_user" "lambda_user" {
  name = "cg-lambda-user-${var.cgid}"
  tags = {
    Name = "cg-lambda-user-${var.cgid}"
    Stack = var.stack-name
    Scenario = var.scenario-name
  }
}

resource "aws_iam_access_key" "lambda_user" {
  user = aws_iam_user.lambda_user.name
}

resource "aws_iam_user_policy" "lambda_user_policy" {
  name = "cg-lambda-user-policy-${var.cgid}"
  user = aws_iam_user.lambda_user.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:ListSecrets",
          "secretsmanager:DescribeSecret"
        ]
        Resource = "*"
      }
    ]
  })
}

# Create a dummy zip file for the lambda function
data "archive_file" "lambda_zip" {
  type        = "zip"
  output_path = "${path.module}/lambda_function.zip"

  source {
    content  = "def lambda_handler(event, context): return 'Hello from CloudGoat'"
    filename = "lambda_function.py"
  }
}

resource "aws_iam_role" "lambda_exec_role" {
  name = "cg-lambda-exec-role-${var.cgid}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "lambda.amazonaws.com"
      }
    }]
  })
}

resource "aws_lambda_function" "sensitive_lambda" {
  filename      = data.archive_file.lambda_zip.output_path
  function_name = "cg-lambda-function-${var.cgid}"
  role          = aws_iam_role.lambda_exec_role.arn
  handler       = "lambda_function.lambda_handler"
  runtime       = "python3.9"

  # VULNERABILITY: Credentials stored in Environment Variables
  environment {
    variables = {
      DB_USER_ACCESS_KEY = aws_iam_access_key.lambda_user.id
      DB_USER_SECRET_KEY = aws_iam_access_key.lambda_user.secret
    }
  }

  tags = {
    Name = "cg-lambda-${var.cgid}"
    Stack = var.stack-name
    Scenario = var.scenario-name
  }
}

output "start_user_access_key" {
  description = "The access key for the starting user"
  value       = aws_iam_access_key.start_user.id
}

output "start_user_secret_key" {
  description = "The secret key for the starting user"
  value       = aws_iam_access_key.start_user.secret
  sensitive   = true
}

## This is used for the CloudGoat scenario to pull the AWS profile from the CloudGoat configuration.
## Configure required Terraform and provider versions.

terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.74.0"
    }
  }
}

provider "aws" {
  profile = var.profile
  region  = var.region

  # This configures default tags for all resources
  default_tags {
    tags = {
      Stack    = var.stack-name
      Scenario = var.scenario-name
    }
  }
}

resource "aws_secretsmanager_secret" "final_flag" {
  name = "cg-final-flag-${var.cgid}"
  description = "The final flag for the CloudGoat scenario"

  tags = {
    Name = "cg-final-flag-${var.cgid}"
    Stack = var.stack-name
    Scenario = var.scenario-name
  }
}

resource "aws_secretsmanager_secret_version" "final_flag_value" {
  secret_id     = aws_secretsmanager_secret.final_flag.id
  secret_string = jsonencode({
    flag = "d4t4_s3cr3ts_4r3_fun"
  })
}

variable "profile" {
  description = "The AWS profile to use when deploying resources"
  type        = string
}

variable "region" {
  description = "The AWS region to deploy resources into"
  default     = "us-east-1"
  type        = string
}

variable "cgid" {
  description = "CGID variable for unique naming between scenarios"
  type        = string
}

# This resources is not needed for scenarios, but should be used on any public facing resources
variable "cg_whitelist" {
  description = "User's public IP address(es)"
  type        = list(string)
}

variable "stack-name" {
  description = "Name of the stack"
  default     = "CloudGoat"
  type        = string
}

variable "scenario-name" {
  description = "Name of the scenario being deployed"
  default     = "scenario_template"
  type        = string
}

resource "aws_vpc" "vpc" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "cg-vpc-${var.cgid}"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.vpc.id
  tags = {
    Name = "cg-igw-${var.cgid}"
  }
}

resource "aws_subnet" "subnet" {
  vpc_id                  = aws_vpc.vpc.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = "us-east-1a"
  map_public_ip_on_launch = true

  tags = {
    Name = "cg-subnet-${var.cgid}"
  }
}

resource "aws_route_table" "route_table" {
  vpc_id = aws_vpc.vpc.id
  tags = {
    Name = "cg-route-table-${var.cgid}"
  }
}

resource "aws_route" "route" {
  route_table_id         = aws_route_table.route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.igw.id
}

resource "aws_route_table_association" "route_table_association" {
  subnet_id      = aws_subnet.subnet.id
  route_table_id = aws_route_table.route_table.id
}
